import{_ as n,a8 as o,o as i,c as r,ah as l,K as a}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const b=JSON.parse('{"title":"Edit 工具对含特殊 Unicode 字符的文本匹配会失败","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["工具","Edit","HTML","踩坑"]},"headers":[],"relativePath":"vault/Memory/Lessons/HTML编辑特殊字符匹配失败.md","filePath":"vault/Memory/Lessons/HTML编辑特殊字符匹配失败.md","lastUpdated":1789374053000}'),s={name:"vault/Memory/Lessons/HTML编辑特殊字符匹配失败.md"};function c(_,e,p,h,m,u){const t=o("NolebaseGitContributors"),d=o("NolebaseGitChangelog");return i(),r("div",null,[e[0]||(e[0]=l('<h1 id="edit-工具对含特殊-unicode-字符的文本匹配会失败" tabindex="-1">Edit 工具对含特殊 Unicode 字符的文本匹配会失败 <a class="header-anchor" href="#edit-工具对含特殊-unicode-字符的文本匹配会失败" aria-label="Permalink to “Edit 工具对含特殊 Unicode 字符的文本匹配会失败”">​</a></h1><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to “现象”">​</a></h2><p>用 Edit 工具修改含中文弯引号（&quot;&quot;）、Unicode 箭头（→ U+2192）、中文破折号（——）的 HTML/文档时，<code>old_string</code> 看起来与文件内容一致，却反复报 &quot;String to replace not found&quot;。肉眼和 grep 都确认字符相同，仍匹配失败。多份中文 HTML（帮老适框架/案例库）中反复出现。</p><h2 id="解法" tabindex="-1">解法 <a class="header-anchor" href="#解法" aria-label="Permalink to “解法”">​</a></h2><p>改用 node_repl 做替换，两种方式按可靠性排序：</p><ol><li><strong>整块含特殊字符时</strong>：<code>fs.readFileSync</code> 读入 → 用不含特殊字符的唯一锚点 <code>indexOf</code> 定位 → <code>lastIndexOf</code> 找块起点 → 字符串切片拼接替换 → <code>writeFileSync</code> 写回。</li><li><strong>replace 可用时</strong>：在 node 里用 <code>s.replace(old, new)</code>，old 直接从 Read 输出复制（node 处理 Unicode 与 Edit 工具的编码路径不同，成功率更高）。</li></ol><p>替换后务必校验：div 开闭计数平衡、关键新增词 grep 确认、旧词残留确认。</p><h2 id="教训" tabindex="-1">教训 <a class="header-anchor" href="#教训" aria-label="Permalink to “教训”">​</a></h2><ul><li>Edit 工具的字符串匹配在 Windows + 中文 + 特殊标点场景不可靠，<strong>多个中文文档批量修改时直接上 node_repl，不要在 Edit 上反复重试浪费时间</strong>。</li><li>每次替换后做结构校验（div 平衡）是最后防线，本次会话中多次靠它发现替换未生效。</li></ul>',9)),a(t),a(d)])}const T=n(s,[["render",c]]);export{b as __pageData,T as default};
